import { createAction, props } from '@ngrx/store';
import { Temple } from '../../core/models/temple.model';

export const loadTemples = createAction('[Temple List] Load Temples');
export const loadTemplesSuccess = createAction(
    '[Temple List] Load Temples Success',
    props<{ temples: Temple[] }>()
);
export const loadTemplesFailure = createAction(
    '[Temple List] Load Temples Failure',
    props<{ error: any }>()
);
